class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def distributeCandy(self, root: TreeNode) -> int:
        self.moves = 0

        def dfs(node):
            if not node:
                return 0
            left_excess = dfs(node.left)
            right_excess = dfs(node.right)
            current_excess = node.val - 1 + left_excess + right_excess
            self.moves += abs(left_excess) + abs(right_excess)
            return current_excess

        dfs(root)
        return self.moves
